import{_ as e,o as t,c as o,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Flow: ritmo sostenible","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/flow.md","filePath":"es/guide/combat/flow.md"}'),i={name:"es/guide/combat/flow.md"};function r(d,a,s,l,c,m){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="flow-sustainable-rhythm" tabindex="-1">Flow: ritmo sostenible <a class="header-anchor" href="#flow-sustainable-rhythm" aria-label="Enlace permanente a &quot;Flow: ritmo sostenible&quot;">​</a></h1><p><strong>Estado:</strong> Experimental para el perfil numérico · No implementado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Flow recompensa un ritmo Modern estable con pequeños beneficios de eficiencia de estado Experimental.</li><li>No concede daño bruto ni bonificación de precisión y nunca omite la recuperación.</li><li>Las pausas borran Flow sin castigar la inactividad; Legacy usa cadencia automática en su lugar.</li></ul><p>Flow recompensa un ritmo Modern estable y tolerante. No exige un BPM perfecto, y las pulsaciones extra nunca omiten la recuperación.</p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Estado</th><th>Stamina</th><th>Recuperación</th><th>Significado</th></tr></thead><tbody><tr><td>Off Rhythm</td><td>+5%</td><td>+5%</td><td>Las entradas apresuradas reducen eficiencia</td></tr><tr><td>Stable</td><td>Normal</td><td>Normal</td><td>Juego ordinario</td></tr><tr><td>Flow</td><td>−5%</td><td>−5%</td><td>Tres intervalos estables conceden el beneficio a la siguiente acción</td></tr></tbody></table><p>Son factores con estado Experimental antes del redondeo final y otros modificadores. Las señales de consistencia cambian cualitativamente; Flow no concede bonificación de daño bruto ni precisión.</p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Separación de entradas</th><th>Resultado</th></tr></thead><tbody><tr><td>85–135% del ritmo de referencia de la acción</td><td>Intervalo Normal; aumenta la racha</td></tr><tr><td>70–menos de 85%</td><td>Slightly rushed; se borra la racha</td></tr><tr><td>Menos de 70%</td><td>Off Rhythm; costes adicionales por apresurarse</td></tr><tr><td>Más de 135%</td><td>Pausa; borra Flow sin castigar la inactividad</td></tr></tbody></table><ul><li>El ritmo de referencia procede del wind-up de la acción anterior, su fase activa y 1.5× la recuperación base.</li><li>Tres pulsaciones no disponibles dentro de 500 ms activan Off Rhythm, no ataques extra.</li><li>Una gran variación entre intervalos consecutivos que no sean pausas también entra en Off Rhythm; las pausas ordinarias no se castigan.</li><li>Tres intervalos Normal recuperan Stable desde Off Rhythm; otros tres entran en Flow.</li><li>Fintas, defensa, cambios de objetivo y cambios de arma/modo reinician la racha.</li><li>Legacy usa cadencia automática en lugar de Flow.</li></ul><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Longsword Basic Slash tiene un ritmo de referencia de 1300 ms. Una continuación a 1200 ms es Normal; una a 1000 ms es Slightly rushed y cuesta más. La disponibilidad sigue condicionando ambas.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/stamina-and-reactive-combat.html">Stamina</a> · <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html#flow-test">Reglas exactas de estado y redondeo</a> · <a href="/Syrolands-Public/es/game-design/combat/flow.html">Diseño completo de Flow</a></p><p><span id="flow-rhythm-without-button-mashing"></span></p>',16)])])}const p=e(i,[["render",r]]);export{h as __pageData,p as default};
